module Datapath_BEH #(parameter dp_width = 8, R2_width = 4)(   output [R2_width -1: 0] count, output reg E, output Zero, input [dp_width -1: 0] data,   input Load_regs, Shift_left, Incr_R2, clock, reset_b);  reg [dp_width -1: 0] R1;  reg [R2_width -1: 0] R2;    assign count = R2;  assign Zero = ~(| R1);  always @ (posedge clock) begin    E <= R1[dp_width -1] & Shift_left;    if (Load_regs) begin R1 <= data; R2 <= {R2_width{1'b1}}; end    if (Shift_left) {E, R1} <= {E, R1} << 1;    if (Incr_R2) R2 <= R2 + 1;  endendmodule// Test Plan for Datapath Unit:// Demonstrate action of Load_regs// 	R1 gets data, R2 gets all ones// Demonstrate action of Incr_R2// Demonstrate action of Shift_left and detect E// Test bench for datapathmodule t_Datapath_Unit #(parameter dp_width = 8, R2_width = 4)( );  wire [R2_width -1: 0] 	count;  wire 					E, Zero;  reg [dp_width -1: 0] 	data;   reg 						Load_regs, Shift_left, Incr_R2, clock, reset_b;  Datapath_BEH M0 (count, E, Zero, data, Load_regs, Shift_left, Incr_R2, clock, reset_b);  initial #250 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin reset_b = 0; #2 reset_b = 1; end  initial fork    data = 8'haa;    Load_regs = 0;    Incr_R2 = 0;    Shift_left = 0;    #10 Load_regs = 1;    #20 Load_regs = 0;    #50 Incr_R2 = 1;    #120 Incr_R2 = 0;    #90 Shift_left = 1;    #200 Shift_left = 0;  joinendmodule